def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    from collections import deque

    counts = []
    window = deque()  # (height, index), decreasing by height

    for i, height in enumerate(a):
        while window and window[0][1] < i - k:
            window.popleft()

        # The window's entries are the undominated heights in the range.
        # To count all taller people, use a Fenwick tree instead.
        counts.append(0)

    # Coordinate-compressed Fenwick tree for sliding-window height counts.
    values = sorted(set(a))
    ranks = {value: i + 1 for i, value in enumerate(values)}
    tree = [0] * (len(values) + 1)

    def add(index: int, delta: int) -> None:
        while index < len(tree):
            tree[index] += delta
            index += index & -index

    def prefix_sum(index: int) -> int:
        total = 0
        while index:
            total += tree[index]
            index -= index & -index
        return total

    result = []
    for i, height in enumerate(a):
        if i >= k:
            add(ranks[a[i - k]], -1)
        rank = ranks[height]
        result.append(i - max(0, i - k) - prefix_sum(rank))
        add(rank, 1)

    return result
